export const CARDS_BY_ID = Object.fromEntries(CARDS.map((card) => [card.id, card]));

export const CARDS_BY_TYPE = CARDS.reduce((acc, card) => {
  (acc[card.type] ||= []).push(card);
  return acc;
}, {});

